window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7332d20bd13e54bb"]={"versions": [{"id": "FIG-7332d20bd13e54bb", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein hierarchisches Klassifikations- bzw. Taxonomie-Diagramm zur Strukturierung von Display-Typen und Display-Technologien im Kontext des ECU-Ressourcen-Modells (AUTOSAR_ResourceTemplateECU). Es visualisiert eine zweistufige funktionale bzw. anwendungsspezifische Kategorisierung sowie eine technologiebasierte Untergliederung hardwareseitiger Ausprägungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende hierarchisch gegliederte Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten:</strong> <code>Display</code> (türkise Box) als generische Basiskategorie für Display-Ressourcen.</li>\n<li><strong>Funktionale Klassifikationsebene (erste Sub-Ebene, türkis):</strong></li>\n<li><code>Numerical</code>: Anzeige für rein numerische Werte/Segmente.</li>\n<li><code>Alphanumerical</code>: Anzeige für alphanumerische Zeichenketten.</li>\n<li><code>Graphical</code>: Vollgrafische Punktmatrix- bzw. Pixelanzeige.</li>\n</ul>\n<p class=\"fig-p\">Die drei Ausprägungen sind über einen gemeinsamen Verteilerknoten mit der Basiskategorie sowie der darunterliegenden Technologie-Ebene verknüpft.</p>\n<ul class=\"fig-list\">\n<li><strong>Technologie-Klassifikationsebene (<code>Technologies</code>, gelbe Boxen):</strong></li>\n<li><code>OLED</code>: Organic Light Emitting Diode.</li>\n<li><code>LED</code>: Light Emitting Diode.</li>\n<li><code>LCD</code>: Liquid Crystal Display.</li>\n<li><code>VCD</code>: Vacuum Fluorescent Display / Vacuum Cathode Display (VCD/VFD-Technologie).</li>\n<li><strong>Spezifische LCD-Technologien (Unterebene von LCD, gelb):</strong></li>\n<li><code>STN</code>: Super Twisted Nematic LCD.</li>\n<li><code>TFT</code>: Thin Film Transistor LCD.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Taxonomie und Hardware-Klassifikationsmodell enthält das Diagramm keine zeitlichen Sequenzabläufe, Nachrichtenflüsse oder dynamischen Zustandsübergänge. Die Verknüpfungslinien definieren taxonomische Spezialisierungs- und Zuordnungsbeziehungen zwischen funktionalem Anzeigetyp und physikalischer Implementierungstechnologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der Spezifikation und Konfiguration von Display-Peripheriegeräten und Hardware-Ressourcen in der ECU-Ressourcenbeschreibung. Systemintegratoren und Treiberentwickler müssen bei der Modellierung von ECU-Displays sowohl die funktionale Schnittstelle/Darstellungsart (<code>Numerical</code>, <code>Alphanumerical</code>, <code>Graphical</code>) als auch die physikalische Treibertechnologie (<code>OLED</code>, <code>LED</code>, <code>LCD</code> mit <code>STN</code>/<code>TFT</code>, <code>VCD</code>) im Beschreibungsmodell passend zuordnen.</p>"}, {"id": "FIG-2955c8589d0204e9", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine unbeschriftete hierarchische Baumstruktur (Strukturgerüst) dar. Es visualisiert eine generische Klassifikationshierarchie mit Wurzelknoten, einer dreiteiligen ersten Zwischenebene und einer viergeteilten zweiten Ebene mit zweifacher Untergliederung, jedoch ohne textuelle Semantik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm besteht aus unbeschrifteten Kategorienelementen und Verbindungslinien:</p>\n<ul class=\"fig-list\">\n<li>Ein zentraler Wurzelknoten (türkise Box) auf oberster Ebene.</li>\n<li>Eine mittlere funktionale Ebene bestehend aus drei parallelen, unbeschrifteten türkisen Boxen, die über ein gemeinsames Liniennetzwerk gebündelt werden.</li>\n<li>Eine untere Ebene bestehend aus vier separaten, unbeschrifteten gelben Boxen.</li>\n<li>Eine Sub-Ebene unter der dritten gelben Box, bestehend aus zwei weiteren unbeschrifteten gelben Boxen.</li>\n</ul>\n<p class=\"fig-p\">Alle Beschriftungen und Textannotationen fehlen vollständig.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Taxonomie und Hardware-Klassifikationsmodell enthält das Diagramm keine zeitlichen Sequenzabläufe, Nachrichtenflüsse oder dynamischen Zustandsübergänge. Die Verknüpfungslinien definieren taxonomische Spezialisierungs- und Zuordnungsbeziehungen zwischen funktionalem Anzeigetyp und physikalischer Implementierungstechnologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Aufgrund der vollständig fehlenden Beschriftungen und Semantik besitzt das Schaubild in dieser Fassung keinen normativ nutzbaren Informationsgehalt zur Konfiguration von Display-Ressourcen oder Steuergeräte-Treibern. Entwickler können dem Diagramm lediglich die reine Baumtopologie entnehmen.</p>"}, {"id": "FIG-c73b1c37204abaa6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein hierarchisches Klassifikations- bzw. Taxonomie-Diagramm zur Strukturierung von Display-Typen und Display-Technologien im Kontext des ECU-Ressourcen-Modells (AUTOSAR_ResourceTemplateECU). Es visualisiert eine zweistufige funktionale bzw. anwendungsspezifische Kategorisierung sowie eine technologiebasierte Untergliederung hardwareseitiger Ausprägungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende hierarchisch gegliederte Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten:</strong> <code>Display</code> (türkise Box) als generische Basiskategorie für Display-Ressourcen.</li>\n<li><strong>Funktionale Klassifikationsebene (erste Sub-Ebene, türkis):</strong></li>\n<li><code>Numerical</code>: Anzeige für rein numerische Werte/Segmente.</li>\n<li><code>Alphanumerical</code>: Anzeige für alphanumerische Zeichenketten.</li>\n<li><code>Graphical</code>: Vollgrafische Punktmatrix- bzw. Pixelanzeige.</li>\n</ul>\n<p class=\"fig-p\">Die drei Ausprägungen sind über einen gemeinsamen Verteilerknoten mit der Basiskategorie sowie der darunterliegenden Technologie-Ebene verknüpft.</p>\n<ul class=\"fig-list\">\n<li><strong>Technologie-Klassifikationsebene (<code>Technologies</code>, gelbe Boxen):</strong></li>\n<li><code>OLED</code>: Organic Light Emitting Diode.</li>\n<li><code>LED</code>: Light Emitting Diode.</li>\n<li><code>LCD</code>: Liquid Crystal Display.</li>\n<li><code>VCD</code>: Vacuum Fluorescent Display / Vacuum Cathode Display (VCD/VFD-Technologie).</li>\n<li><strong>Spezifische LCD-Technologien (Unterebene von LCD, gelb):</strong></li>\n<li><code>STN</code>: Super Twisted Nematic LCD.</li>\n<li><code>TFT</code>: Thin Film Transistor LCD.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Taxonomie und Hardware-Klassifikationsmodell enthält das Diagramm keine zeitlichen Sequenzabläufe, Nachrichtenflüsse oder dynamischen Zustandsübergänge. Die Verknüpfungslinien definieren taxonomische Spezialisierungs- und Zuordnungsbeziehungen zwischen funktionalem Anzeigetyp und physikalischer Implementierungstechnologie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild dient der Spezifikation und Konfiguration von Display-Peripheriegeräten und Hardware-Ressourcen in der ECU-Ressourcenbeschreibung. Systemintegratoren und Treiberentwickler müssen bei der Modellierung von ECU-Displays sowohl die funktionale Schnittstelle/Darstellungsart (<code>Numerical</code>, <code>Alphanumerical</code>, <code>Graphical</code>) als auch die physikalische Treibertechnologie (<code>OLED</code>, <code>LED</code>, <code>LCD</code> mit <code>STN</code>/<code>TFT</code>, <code>VCD</code>) im Beschreibungsmodell passend zuordnen.</p>"}], "trans": [{"from": "FIG-7332d20bd13e54bb", "to": "FIG-2955c8589d0204e9", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Alle Textbeschriftungen („Display“, „Numerical“, „Alphanumerical“, „Graphical“, „Technologies“, „OLED“, „LED“, „LCD“, „VCD“, „STN“, „TFT“) wurden aus den Diagramm-Boxen und der Beschriftungsebene entfernt, sodass eine leere Boxenstruktur ohne semantische Bezeichner verbleibt.</li>\n</ul>"}, {"from": "FIG-2955c8589d0204e9", "to": "FIG-c73b1c37204abaa6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Alle zuvor entfernten Textbeschriftungen („Display“, „Numerical“, „Alphanumerical“, „Graphical“, „Technologies“, „OLED“, „LED“, „LCD“, „VCD“, „STN“, „TFT“) wurden wieder in die Boxen und an die Technologie-Ebene eingefügt.</li>\n</ul>"}]};
